<!DOCTYPE html><html lang="th"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>รายการคำสั่งซื้อ - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css?v=<?= filemtime(__DIR__.'/../assets/css/styles.css') ?>"><style>*{box-sizing:border-box}.account{display:flex;width:100%;min-height:900px}.orders-content{flex:1;max-width:1040px;margin:0 auto;padding:38px 50px 90px;min-width:0}.title{font-size:34px;color:var(--secondary-color);margin:0}.subtitle{margin:4px 0 28px;color:var(--text-muted)}.tabs{display:flex;border-bottom:1px solid #eadbd4;margin-bottom:34px;overflow-x:auto}.tabs a{min-width:130px;padding:15px;text-align:center;color:#746b65;text-decoration:none;font-weight:600;border-bottom:3px solid transparent}.tabs a.active{color:var(--secondary-color);border-color:var(--secondary-color)}.search{width:330px;max-width:100%;height:42px;border:1px solid #bbb;border-radius:22px;padding:0 18px;margin-bottom:30px;font:inherit}.order-card{border:1px solid #b9ced2;border-radius:12px;margin-bottom:22px;background:#fff;overflow:hidden;box-shadow:0 2px 4px rgba(0,0,0,.05)}.order-head{display:flex;align-items:center;justify-content:space-between;padding:16px 24px;border-bottom:1px solid #cbdadd}.seller{font-size:18px;font-weight:700}.badge{padding:5px 14px;border-radius:18px;font-size:12px;font-weight:700}.badge.pending,.badge.cancelled{background:#ffdeda;color:#c43c36}.badge.reviewing{background:#fff0cf;color:#9b6b13}.badge.shipping{background:#ffe0dc;color:#bd433d}.badge.completed{background:#e8f5df;color:#457a3a}.items{padding:10px 25px}.order-item{display:grid;grid-template-columns:105px 1fr auto;gap:20px;align-items:center;padding:14px 0;border-bottom:1px solid #eee}.order-item:last-child{border:0}.cover{width:95px;height:125px;border-radius:7px;background:#f9e8df;overflow:hidden}.cover img{width:100%;height:100%;object-fit:cover}.order-item h3{margin:0 0 7px}.order-item p{margin:3px 0;color:var(--text-muted)}.price{font-size:19px;color:var(--secondary-color);font-weight:700}.order-foot{display:flex;align-items:center;justify-content:space-between;padding:15px 24px 20px}.order-number{color:var(--text-muted)}.actions{display:flex;gap:10px}.actions form{display:flex;gap:10px;margin:0}.btn{padding:0 16px;height:44px;border:1px solid var(--secondary-color);border-radius:8px;background:#fff;color:var(--secondary-color);display:inline-flex;align-items:center;justify-content:center;text-decoration:none;font:inherit;font-weight:normal;cursor:pointer;white-space:nowrap}.btn.primary{background:#d3948b;border-color:#d3948b;color:#fff}.btn.dark{background:var(--secondary-color);color:#fff}.empty{text-align:center;padding:110px 20px;color:var(--text-muted)}@media(max-width:1024px){.order-foot{flex-wrap:wrap;gap:12px}.order-number{width:100%}.actions{width:100%;flex-wrap:wrap;justify-content:flex-end}.actions form{flex-wrap:wrap;justify-content:flex-end}}@media(max-width:800px){.account{display:block}.orders-content{padding:20px 12px}.title{font-size:26px}.subtitle{margin:4px 0 16px;font-size:14px}.tabs{margin-bottom:20px}.search{margin-bottom:18px}.order-card{margin-bottom:16px}.order-head{padding:12px 16px}.items{padding:5px 16px}.order-item{grid-template-columns:70px 1fr auto;align-items:flex-start;padding:12px 0;gap:12px}.cover{width:70px;height:90px}.price{grid-column:3;font-size:15px;margin-top:0}.order-item h3{margin:0 0 4px;font-size:15px}.order-item p{margin:2px 0;font-size:13px}.order-foot{padding:12px 16px 14px;gap:10px}.actions{gap:8px}.actions form{gap:8px}.btn{padding:0 12px;height:38px;font-size:14px}.order-number{font-size:13px}.tabs a{min-width:115px}}@media(max-width:500px){.order-item{grid-template-columns:70px 1fr}.price{grid-column:2;margin-top:5px}.order-foot{align-items:flex-start}.actions{width:100%}.actions form{flex:1;display:flex;flex-wrap:nowrap}.actions form .btn, .actions > .btn{flex:1;width:100%;padding:0 8px}}</style></head><body><?php require __DIR__.'/../components/header.php';?><div class="account"><?php require __DIR__.'/../components/profile_sidebar.php';?><main class="orders-content"><h1 class="title">รายการคำสั่งซื้อของฉัน</h1><p class="subtitle">ติดตามสถานะและประวัติการสั่งซื้อหนังสือของคุณทั้งหมดได้ที่นี่</p><nav class="tabs"><?php foreach(['all'=>'ทั้งหมด','pending'=>'รอการชำระ','shipping'=>'กำลังจัดส่ง','completed'=>'สำเร็จแล้ว','cancelled'=>'ยกเลิกแล้ว'] as $key=>$label):?><a class="<?=$tab===$key?'active':''?>" href="?tab=<?=$key?>"><?=$label?></a><?php endforeach;?></nav><form><input type="hidden" name="tab" value="<?=htmlspecialchars($tab)?>"><input class="search" name="q" value="<?=htmlspecialchars($q)?>" placeholder="ค้นหาชื่อหนังสือ หรือหมายเลขคำสั่งซื้อ"></form>
<?php if(!$orders):?><div class="empty">ไม่พบรายการคำสั่งซื้อในหมวดนี้</div><?php else:foreach($orders as $o):[$state,$stateClass]=orderState($o);$sellerNames=array_values(array_unique(array_map('orderSellerName',$o['items'])));$reviewableItems=array_values(array_filter($o['items'],fn($i)=>!empty($i['book_id'])));$reviewedCount=count(array_filter($reviewableItems,fn($i)=>!empty($i['review_id'])));?><article class="order-card"><header class="order-head"><span class="seller"><span class="seller-store-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 10v9h16v-9M3 10l2-5h14l2 5M3 10c0 1.1.9 2 2 2s2-.9 2-2c0 1.1.9 2 2 2s2-.9 2-2c0 1.1.9 2 2 2s2-.9 2-2c0 1.1.9 2 2 2s2-.9 2-2c0 1.1.9 2 2 2s2-.9 2-2M9 19v-4h6v4"/></svg></span><?=htmlspecialchars(implode(', ',$sellerNames)?:'ร้านวนวรรณ')?></span><span class="badge <?=$stateClass?>"><?=$state?></span></header><div class="items"><?php foreach($o['items'] as $item):?><div class="order-item"><div class="cover"><?php if($img=orderImage($item['image_cover'])):?><img src="<?=htmlspecialchars($img)?>" alt=""><?php endif;?></div><div><h3><?=htmlspecialchars($item['title']?:'หนังสือ')?></h3><p>ผู้เขียน: <?=htmlspecialchars($item['author']?:'-')?></p><p>จำนวน: ×<?=$item['quantity']?></p><?php if($stateClass==='completed'&&!empty($item['book_id'])):?><a class="review-btn <?=$item['review_id']?'is-reviewed':''?>" href="/pages/review_order.php?order_id=<?=(int)$o['order_id']?>#item-<?=(int)$item['order_item_id']?>"><span class="review-btn-icon">★</span><span><?=$item['review_id']?'แก้ไขรีวิวเล่มนี้':'รีวิวหนังสือเล่มนี้'?></span><span class="review-btn-arrow">›</span></a><?php endif;?></div><div class="price">฿<?=number_format($item['price_at_purchase']*$item['quantity'],2)?></div></div><?php endforeach;?></div><footer class="order-foot"><span class="order-number">หมายเลขคำสั่งซื้อ: <strong><?=htmlspecialchars($o['order_number'])?></strong></span><div class="actions"><?php if($stateClass==='completed'&&$reviewableItems):?><a class="btn primary order-review-btn" href="/pages/review_order.php?order_id=<?=(int)$o['order_id']?>"><span aria-hidden="true">☆</span> รีวิวสินค้า <?=$reviewedCount?>/<?=count($reviewableItems)?> เล่ม</a><?php endif;?><?php if(($stateClass==='completed'||$stateClass==='shipping')&&(!isset($o['payout_status'])||$o['payout_status']==='pending')) :?><a class="btn" style="border-color:#e8546a;color:#e8546a;" href="/pages/dispute.php?order_id=<?=(int)$o['order_id']?>">เปิดข้อพิพาท/คืนเงิน</a><?php endif;?><a class="btn" href="/pages/order_receipt.php?number=<?=urlencode($o['order_number'])?>">ดูรายละเอียด</a><?php if($stateClass==='pending'):?><form method="post"><input type="hidden" name="order_id" value="<?=$o['order_id']?>"><button class="btn" name="cancel">ยกเลิกคำสั่งซื้อ</button><a class="btn primary" href="/pages/payment.php?order=<?=$o['order_id']?>">ชำระเงิน</a></form><?php elseif(in_array($stateClass,['completed','cancelled'],true)):?><form method="post"><input type="hidden" name="order_id" value="<?=$o['order_id']?>"><button class="btn dark" name="buy_again">ซื้ออีกครั้ง</button></form><?php endif;?></div></footer></article><?php endforeach;endif;?></main></div><?php require __DIR__.'/../components/footer.php';?></body></html>
